# Most teams use the console for CloudFront (complex config)
# Here's the CLI approach for a simple S3 + HTTPS setup:

# Create distribution pointing to S3 bucket website endpoint
aws cloudfront create-distribution --distribution-config '{
  "Comment": "My App CDN",
  "DefaultRootObject": "index.html",
  "Origins": {
    "Quantity": 1,
    "Items": [{
      "Id": "S3-myapp",
      "DomainName": "myapp-bucket.s3-website-ap-south-1.amazonaws.com",
      "CustomOriginConfig": {
        "HTTPPort": 80,
        "OriginProtocolPolicy": "http-only"
      }
    }]
  },
  "DefaultCacheBehavior": {
    "TargetOriginId": "S3-myapp",
    "ViewerProtocolPolicy": "redirect-to-https",
    "CachePolicyId": "658327ea-f89d-4fab-a63d-7e88639e58f6",
    "Compress": true
  },
  "ViewerCertificate": {
    "CloudFrontDefaultCertificate": true
  },
  "Enabled": true,
  "PriceClass": "PriceClass_All"
}'

# Result: CloudFront domain like abc123.cloudfront.net
# Point your custom domain's CNAME to this

# Invalidate cache after deploying new files
aws cloudfront create-invalidation \
  --distribution-id EXXXXXXXXXX \
  --paths '/*'   # invalidate all cached files
  # or specific: '/index.html' '/static/*'
